    });

    const defaultProps = {
        matrixClient: mockClient,
        makeRequest: jest.fn().mockResolvedValue(undefined),
        onFinished: jest.fn(),
    };
    const getComponent = (props = {}) => mount(<InteractiveAuthDialog {...defaultProps} {...props} />);

