    afterAll(() => {
        unmockClientPeg();
    });

    const getSubmitButton = (wrapper: ReactWrapper) => wrapper.find('[type="submit"]').at(0);

    it("Should successfully complete a password flow", async () => {
        const onFinished = jest.fn();
        const makeRequest = jest.fn().mockResolvedValue({ a: 1 });

